SELECT * FROM ( SELECT a.*, ROWNUM rnum FROM ( SELECT PREC_ID as precId, CASE_NO as caseNo, COURT, TO_CHAR(JUDGE_DATE, 'YYYY-MM-DD') as judgeDate, CASE_TYPE as caseType, TITLE, ONE_LINE as oneLine, JUDGMENT, KEYWORD_CSV as keywordCsv FROM TB_PRECEDENT
AND (UPPER(TITLE) LIKE '%' || UPPER(TRIM(#{query})) || '%' OR UPPER(CASE_NO) LIKE '%' || UPPER(TRIM(#{query})) || '%' OR UPPER(KEYWORD_CSV) LIKE '%' || UPPER(TRIM(#{query})) || '%')
AND CASE_TYPE = #{caseType}
ORDER BY PREC_ID DESC ) a WHERE ROWNUM <= #{end} ) WHERE rnum >= #{start}

SELECT COUNT(*) FROM TB_PRECEDENT
AND (UPPER(TITLE) LIKE '%' || UPPER(TRIM(#{query})) || '%' OR UPPER(CASE_NO) LIKE '%' || UPPER(TRIM(#{query})) || '%' OR UPPER(KEYWORD_CSV) LIKE '%' || UPPER(TRIM(#{query})) || '%')
AND CASE_TYPE = #{caseType}
